def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0:
            return False
    return True

def modular_factorial(num, mod):
    result = 1
    for i in range(1, num + 1):
        result = (result * i) % mod
    return result

solutions = []
for n in range(51, 71):
    p = 2 * n - 1

    if not is_prime(p):
        continue

    # We check if (n+2)! == -1 mod p, which means (n+2)! == p-1 mod p
    target_remainder = p - 1

    # Calculate (n+2)! mod p
    # Note: n+2 is at most 72, p is at most 139. Standard modular exponentiation/multiplication is fine.
    factorial_mod = modular_factorial(n + 2, p)

    if factorial_mod == target_remainder:
        solutions.append(n)

print("Solutions found (n):", solutions)

import math

def K(n):
    if 2 * n - 1 == 0:
        raise ValueError("Denominator is zero")
    # Calculate K(n) = 3 * ((n+2)! + 1) / (2n - 1)
    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1
    if numerator % denominator == 0:
        return True
    return False

# Test range for Candidate A: n=51 to n=70
solutions_in_range_A = []
for n in range(51, 71):
    if K(n):
        solutions_in_range_A.append(n)

print(f"Solutions found in range n=51 to n=70: {solutions_in_range_A}")

